// must_not filter condition implementation
// Excludes points that match the specified condition
pub fn apply_must_not(filter: &Condition, points: &[Point]) -> Vec<Point> {
    points.iter()
        .filter(|point| !condition_matches(point, filter))
        .cloned()
        .collect()
}

// Observed behavior: Collection has points id=1(tag=x), id=2(tag=y)
// Filter must_not: {key: 'tag', match: {value: 'x'}} correctly excludes id=1, returns id=2
